nta.declaration:
/* Load the shared library (absolute path recommended) */
import "/home/beltranaceves/software/group_project/uppaal/http_to_uppaal/libuppaal_nn.so" {


/* Declare the external function (must match the C signature exactly).
   This wrapper expects: 6 y0 values followed by 36 control doubles (flattened).
*/
int uppaal_nn_update(
    double y0_0,double y0_1,double y0_2,double y0_3,double y0_4,double y0_5,
    double c0,double c1,double c2,double c3,double c4,double c5,
    double c6,double c7,double c8,double c9,double c10,double c11,
    double c12,double c13,double c14,double c15,double c16,double c17,
    double c18,double c19,double c20,double c21,double c22,double c23,
    double c24,double c25,double c26,double c27,double c28,double c29,
    double c30,double c31,double c32,double c33,double c34,double c35
);

double uppaal_nn_get_pred(int room_id);

double sharing_array(double& y0[6], int n_y0, double& cy[36], int n_cy);

};

clock time;
clock global_time;

int succ = 0;
const double low = 21.5;
const double high = 22.0;

const double rad_sign_low = 0;
const double rad_sign_high = 50;
const double actuator_room_low = 1;
const double actuator_room_high = 14;

double t_a = 21.04;
double t_b = 21.61;
double t_c = 21.61;

double t_d = 21.87;
double t_e = 21.89;
double t_f = 21.82;

double t_avg;

double error_a = 5;
double error_b = 5;
double error_c = 5;
double error_d = 5;
double error_e = 5;
double error_f = 5;
double error_avg = 5;
double error_acum = 5;

double actuator_rooms = 1; /*values min 1 max is 14*/
double rad_sign = 60;

double actuator_room_a = 1; /*values min 1 max is 14*/
double rad_sign_a = 60;

double actuator_room_b = 1; /*values min 1 max is 14*/
double rad_sign_b = 60;

double actuator_room_c = 1; /*values min 1 max is 14*/
double rad_sign_c = 60;

double actuator_room_d = 1; /*values min 1 max is 14*/
double rad_sign_d = 60;

double actuator_room_e = 1; /*values min 1 max is 14*/
double rad_sign_e = 60;

double actuator_room_f = 1; /*values min 1 max is 14*/
double rad_sign_f = 60;

// Track previous actuator states for wear calculation
double prev_rad_sign_a = 60;
double prev_actuator_room_a = 1;
double prev_rad_sign_b = 60;
double prev_actuator_room_b = 1;
double prev_rad_sign_c = 60;
double prev_actuator_room_c = 1;
double prev_rad_sign_d = 60;
double prev_actuator_room_d = 1;
double prev_rad_sign_e = 60;
double prev_actuator_room_e = 1;
double prev_rad_sign_f = 60;
double prev_actuator_room_f = 1;

// Accumulate wear metrics
int actuator_switches_a = 0;
int actuator_switches_b = 0;
int actuator_switches_c = 0;
int actuator_switches_d = 0;
int actuator_switches_e = 0;
int actuator_switches_f = 0;
int total_actuator_switches = 0;

double error_acum_act = 0.0;  // Combined error + actuator wear
double wear_weight = 0.1;     // Weight factor for actuator wear (adjust as needed)

int update_state() {
    succ = uppaal_nn_update(
	    t_a,t_b,t_c,t_d,t_e,t_f,
	    rad_sign_a,  0.0000,  actuator_room_a,  
	    rad_sign_b,  0.0000,  actuator_room_b,  
	    rad_sign_c,  0.0000,  actuator_room_c,  
	    rad_sign_d,  0.0000,  actuator_room_d,  
	    rad_sign_e,  0.0000,  actuator_room_e,  
	    rad_sign_e,  0.0000,  actuator_room_f, 
	    58.3575, 22.6200,  
	    1.0069,  0.0000,  0.0000,  0.0000,  0.0000,  
	    0.0000,  0.0000,  0.0000,  0.0000,  0.0000,  
	    0.0000,  0.0000,  0.0000,  3.1708,  2.8087,  5.5348
    );

    t_a = uppaal_nn_get_pred(0);
    t_b = uppaal_nn_get_pred(1);
    t_c = uppaal_nn_get_pred(2);
    t_d = uppaal_nn_get_pred(3);
    t_e = uppaal_nn_get_pred(4);
    t_f = uppaal_nn_get_pred(5);

    return succ;
}

int detect_actuator_change(double prev_rad, double curr_rad, double prev_room, double curr_room) {
    int changes = 0;

    // Check if radiator signal changed (with some tolerance for floating point)
    if (prev_rad != curr_rad) {
        changes++;
    }

    // Check if actuator room selection changed
    if (prev_room != curr_room) {
        changes++;
    }

    return changes;
}

void update_actuator_wear() {
    // Detect changes for each room
    int changes_a = detect_actuator_change(prev_rad_sign_a, rad_sign_a, prev_actuator_room_a, actuator_room_a);
    int changes_b = detect_actuator_change(prev_rad_sign_b, rad_sign_b, prev_actuator_room_b, actuator_room_b);
    int changes_c = detect_actuator_change(prev_rad_sign_c, rad_sign_c, prev_actuator_room_c, actuator_room_c);
    int changes_d = detect_actuator_change(prev_rad_sign_d, rad_sign_d, prev_actuator_room_d, actuator_room_d);
    int changes_e = detect_actuator_change(prev_rad_sign_e, rad_sign_e, prev_actuator_room_e, actuator_room_e);
    int changes_f = detect_actuator_change(prev_rad_sign_f, rad_sign_f, prev_actuator_room_f, actuator_room_f);

    // Accumulate total switches
    actuator_switches_a += changes_a;
    actuator_switches_b += changes_b;
    actuator_switches_c += changes_c;
    actuator_switches_d += changes_d;
    actuator_switches_e += changes_e;
    actuator_switches_f += changes_f;
    total_actuator_switches += (changes_a + changes_b + changes_c + changes_d + changes_e + changes_f);

    // Update previous states
    prev_rad_sign_a = rad_sign_a;
    prev_actuator_room_a = actuator_room_a;
    prev_rad_sign_b = rad_sign_b;
    prev_actuator_room_b = actuator_room_b;
    prev_rad_sign_c = rad_sign_c;
    prev_actuator_room_c = actuator_room_c;
    prev_rad_sign_d = rad_sign_d;
    prev_actuator_room_d = actuator_room_d;
    prev_rad_sign_e = rad_sign_e;
    prev_actuator_room_e = actuator_room_e;
    prev_rad_sign_f = rad_sign_f;
    prev_actuator_room_f = actuator_room_f;
}

double compute_error(double current_temp, double low_threshold, double high_threshold) {
    if (current_temp > high_threshold) {
        return current_temp - high_threshold;
    } else if (current_temp < low_threshold) {
        return low_threshold - current_temp;
    } else {
        return 0.0;
    }
}

void update_errors() {
    error_a = compute_error(t_a, low, high);
    error_b = compute_error(t_b, low, high);
    error_c = compute_error(t_c, low, high);
    error_d = compute_error(t_d, low, high);
    error_e = compute_error(t_e, low, high);
    error_f = compute_error(t_f, low, high);
    error_avg = (error_a + error_b + error_c + error_d + error_e + error_f) / 6;
    error_acum = (error_a + error_b + error_c + error_d + error_e + error_f);
    error_acum_act = error_acum + (wear_weight * total_actuator_switches);
    t_avg = (t_a + t_b + t_c + t_d + t_e + t_f) / 6;
}

template.declaration:
double dummy_y0[6];

double matrix[6][6];

void read() {
    double cy[36];

    double res;
    res = sharing_array(dummy_y0, 6, cy, 36);

    for (row:int[0,5]) {
        for (column:int[0,5]) {
            matrix[row][column] = cy[row*6+column];
        }
    }
}

